(function(E){ const x = E["exam-04"] = E["exam-04"] || {units:{}}; (x.units = x.units || {})["x04-r3"] = {"id":"x04-r3","patterns":["RA-history","GT3-nature","PARA-cause","PARA-research"],"title":{"en":"Reading 3: Passage 3 / Section 3","tr":"Reading 3: Passage 3 / Section 3","fa":"Reading ۳: متن ۳ (Passage 3) / بخش ۳ (Section 3)"},"objective":{"en":"In this lesson you will learn to read a book review: complete a summary of the book’s content from a box of ten words, decide YES, NO or NOT GIVEN about the reviewer’s opinions, and answer multiple-choice questions about the reviewer’s judgements.","tr":"Bu derste bir kitap eleştirisini okumayı öğreneceksin: kitabın içeriğinin özetini on kelimelik bir kutudan tamamlayacak, eleştirmenin görüşleri için YES, NO ya da NOT GIVEN kararı verecek ve eleştirmenin yargılarıyla ilgili çoktan seçmeli soruları cevaplayacaksın.","fa":"در این درس یاد می‌گیری نقد یک کتاب را بخوانی: خلاصه‌ی محتوای کتاب را از کادری ده‌کلمه‌ای کامل کنی، درباره‌ی نظرهای منتقد بین YES، NO و NOT GIVEN تصمیم بگیری و به سؤال‌های چندگزینه‌ای درباره‌ی داوری‌های منتقد جواب بدهی."},"objectiveGT":{"en":"In this lesson you will learn to choose a heading for each of seven sections of an article about scientific fieldwork, answer multiple-choice questions on details, and complete a summary with single words.","tr":"Bu derste bilimsel saha çalışması hakkındaki bir makalenin yedi bölümünün her biri için başlık seçmeyi, ayrıntılarla ilgili çoktan seçmeli soruları cevaplamayı ve bir özeti tek kelimelerle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری برای هر کدام از هفت بخش یک مقاله درباره‌ی کار میدانی علمی عنوان انتخاب کنی، به سؤال‌های چندگزینه‌ای درباره‌ی جزئیات جواب بدهی و یک خلاصه را با تک‌کلمه‌ها کامل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 3: a book review","tr":"Reading Passage 3: bir kitap eleştirisi","fa":"Reading Passage 3: نقد یک کتاب"},"objective":{"en":"In this lesson you will learn to read a book review: complete a summary of the book’s content from a box of ten words, decide YES, NO or NOT GIVEN about the reviewer’s opinions, and answer multiple-choice questions about the reviewer’s judgements.","tr":"Bu derste bir kitap eleştirisini okumayı öğreneceksin: kitabın içeriğinin özetini on kelimelik bir kutudan tamamlayacak, eleştirmenin görüşleri için YES, NO ya da NOT GIVEN kararı verecek ve eleştirmenin yargılarıyla ilgili çoktan seçmeli soruları cevaplayacaksın.","fa":"در این درس یاد می‌گیری نقد یک کتاب را بخوانی: خلاصه‌ی محتوای کتاب را از کادری ده‌کلمه‌ای کامل کنی، درباره‌ی نظرهای منتقد بین YES، NO و NOT GIVEN تصمیم بگیری و به سؤال‌های چندگزینه‌ای درباره‌ی داوری‌های منتقد جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"14"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Box","tr":"Kutu","fa":"کادر"},"value":"A-J"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a history of mapmaking","tr":"Bu sınav: harita yapımının tarihi","fa":"این آزمون: تاریخ نقشه‌سازی"},"intro":{"en":"History is among the most frequent Passage 3 subjects, and a book review is a common form: one part reports what the book says (facts), the other gives the reviewer’s opinion (judgements). The tasks test both.","tr":"Tarih, Passage 3’ün en sık konularındandır ve kitap eleştirisi yaygın bir biçimdir: bir kısım kitabın ne söylediğini (gerçekler), diğer kısım eleştirmenin görüşünü (yargılar) verir. Görevler ikisini de ölçer.","fa":"تاریخ از پرتکرارترین موضوع‌های Passage 3 است و نقد کتاب شکل رایجی است: یک بخش می‌گوید کتاب چه می‌گوید (واقعیت‌ها) و بخش دیگر نظر منتقد را می‌دهد (داوری‌ها). تمرین‌ها هر دو را می‌سنجند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-r3-ctx","exam":true,"patterns":["RA-history","PARA-research","PARA-cause"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"A review of a book on mapmaking","tr":"Harita yapımı üzerine bir kitabın eleştirisi","fa":"نقد کتابی درباره‌ی نقشه‌سازی"},"asks":{"en":"A book review: the reviewer describes what the book covers (the history of how maps were made), says which chapters are best, criticises its weaknesses and gives an overall verdict.","tr":"Bir kitap eleştirisi: eleştirmen kitabın neyi kapsadığını (haritaların nasıl yapıldığının tarihi) anlatıyor, hangi bölümlerin en iyi olduğunu söylüyor, zayıf yanlarını eleştiriyor ve genel bir yargıya varıyor.","fa":"نقد یک کتاب: منتقد توضیح می‌دهد کتاب چه چیزهایی را پوشش می‌دهد (تاریخ ساخت نقشه‌ها)، می‌گوید کدام فصل‌ها بهترین‌اند، از ضعف‌هایش انتقاد می‌کند و نظر کلی‌اش را می‌دهد."},"fields":["The author","Before printing","Engraving","Colourists","Surveys and cheaper maps","Weaknesses","Verdict"],"words":[{"a":"focus","b":"the main subject","tr":"odak","fa":"تمرکز"},{"a":"copyist","b":"someone who copies by hand","tr":"kopyacı, müstensih","fa":"نسخه‌بردار"},{"a":"engraving","b":"cutting lines into metal","tr":"gravür, oyma baskı","fa":"حکاکی"},{"a":"identical","b":"exactly the same","tr":"özdeş","fa":"یکسان"},{"a":"reproductions","b":"copies of pictures","tr":"reprodüksiyonlar","fa":"نسخه‌های چاپیِ تصویر"},{"a":"memorable","b":"easy to remember / striking","tr":"akılda kalıcı","fa":"به‌یادماندنی"},{"a":"fund","b":"pay for","tr":"finanse etmek","fa":"تأمین مالی کردن"},{"a":"afford","b":"have enough money for","tr":"... gücü yetmek","fa":"از عهده‌ی هزینه برآمدن"},{"a":"hurried","b":"done too quickly","tr":"aceleye getirilmiş","fa":"سرسری"},{"a":"put off","b":"make someone not want to","tr":"vazgeçirmek","fa":"دلسرد کردن"},{"a":"affection","b":"love / warm feeling","tr":"sevgi","fa":"علاقه"},{"a":"a verdict","b":"a final judgement","tr":"hüküm, yargı","fa":"حکم نهایی"}],"traps":[{"en":"A review mixes praise and criticism. Before you answer YES or NO, check whether the sentence is the reviewer’s praise, the reviewer’s criticism or the author’s own claim.","tr":"Bir eleştiri övgüyle eleştiriyi karıştırır. YES ya da NO demeden önce cümlenin eleştirmenin övgüsü mü, eleştirisi mi yoksa yazarın kendi iddiası mı olduğunu kontrol et.","fa":"نقد تعریف و انتقاد را با هم دارد. قبل از YES یا NO چک کن جمله تعریفِ منتقد است، انتقادِ منتقد یا ادعای خودِ نویسنده‌ی کتاب."},{"en":"A summary box contains words from the passage used in the wrong place, and opposites such as cheaper and expensive. Check both the meaning and the period.","tr":"Özet kutusunda metinden yanlış yerde kullanılmış kelimeler ve cheaper ile expensive gibi zıtlar bulunur. Hem anlamı hem dönemi kontrol et.","fa":"کادر خلاصه کلمه‌هایی از متن را دارد که در جای غلط به کار رفته‌اند و متضادهایی مثل cheaper و expensive. هم معنی و هم دوره‌ی زمانی را چک کن."}],"example":{"text":"\"The chapters on early cameras are fascinating. The final section on smartphones, however, is thin.\"","item":"Statement: The whole book is equally detailed. YES, NO or NOT GIVEN?","answer":"NO","why":{"en":"The reviewer praises one part and calls another \"thin\", so the book is not equally detailed.","tr":"Eleştirmen bir bölümü övüyor, diğerine \"zayıf\" diyor; yani kitap her yerde aynı ayrıntıda değil.","fa":"منتقد یک بخش را تحسین می‌کند و بخش دیگر را «ضعیف» می‌نامد، پس کتاب همه‌جا به یک اندازه مفصل نیست."}}},{"id":"RA-culture","ctx":["RA-history","RA-culture"],"title":{"en":"Arguments about art, heritage and history","tr":"Sanat, miras ve tarih üzerine tartışma yazıları","fa":"نوشته‌های استدلالی درباره‌ی هنر، میراث و تاریخ"},"asks":{"en":"A review or an argument about art, museums, heritage or history: should museums return objects, is street art real art, what a history book gets right. YES/NO/NOT GIVEN asks about the writer’s views; multiple choice asks about the writer’s purpose.","tr":"Sanat, müzeler, kültürel miras ya da tarih üzerine bir eleştiri veya tartışma yazısı: müzeler eserleri iade etmeli mi, sokak sanatı gerçek sanat mı, bir tarih kitabı neyi doğru yapıyor. YES/NO/NOT GIVEN yazarın görüşlerini sorar; çoktan seçmeli sorular yazarın amacını sorar.","fa":"نقد یا نوشته‌ای استدلالی درباره‌ی هنر، موزه‌ها، میراث یا تاریخ: آیا موزه‌ها باید اشیا را پس بدهند، آیا هنر خیابانی هنر واقعی است، یک کتاب تاریخ چه چیزی را درست می‌گوید. YES/NO/NOT GIVEN نظر نویسنده را می‌پرسد؛ چندگزینه‌ای هدف نویسنده را."},"fields":["The writer believes the book is too long. (YES / NO / NOT GIVEN)","The writer’s main point in paragraph 3 is...","Museums should charge for entry. (YES / NO / NOT GIVEN)","Summary with a box: the writer thinks the ___ of the exhibition was..."],"words":[{"a":"the writer believes","b":"in my view / I would argue","tr":"yazara göre","fa":"نویسنده معتقد است"},{"a":"convincing","b":"persuasive / makes a strong case","tr":"ikna edici","fa":"قانع‌کننده"},{"a":"overrated","b":"praised more than it deserves","tr":"abartılmış","fa":"بیش از اندازه ستوده‌شده"},{"a":"neglected","b":"ignored / overlooked","tr":"ihmal edilmiş","fa":"نادیده‌گرفته‌شده"},{"a":"authentic","b":"genuine / the real thing","tr":"özgün","fa":"اصیل"},{"a":"controversial","b":"causes disagreement","tr":"tartışmalı","fa":"بحث‌برانگیز"},{"a":"heritage","b":"the past a community keeps","tr":"kültürel miras","fa":"میراث"},{"a":"accessible","b":"easy for the public to reach or understand","tr":"erişilebilir","fa":"در دسترس"},{"a":"criticise","b":"find fault with","tr":"eleştirmek","fa":"انتقاد کردن"},{"a":"underestimate","b":"think it matters less than it does","tr":"küçümsemek","fa":"دست‌کم گرفتن"},{"a":"admittedly","b":"it is true that... but","tr":"kabul etmek gerekir ki","fa":"البته"},{"a":"dismiss","b":"reject without serious thought","tr":"önemsememek","fa":"رد کردن"}],"traps":[{"en":"Reported views: \"some critics say the exhibition is too small\" is not the writer’s view unless the writer agrees.","tr":"Aktarılan görüşler: \"bazı eleştirmenler serginin küçük olduğunu söylüyor\" yazar katılmadıkça yazarın görüşü değildir.","fa":"نظرهای نقل‌شده: «بعضی منتقدها می‌گویند نمایشگاه کوچک است» نظر نویسنده نیست، مگر اینکه نویسنده موافق باشد."},{"en":"NOT GIVEN: the writer discusses the topic but gives no opinion on the exact point of the statement.","tr":"NOT GIVEN: yazar konuyu tartışır ama ifadedeki noktaya dair görüş bildirmez.","fa":"NOT GIVEN: نویسنده درباره‌ی موضوع حرف می‌زند، ولی درباره‌ی همان نکته‌ی جمله نظری نمی‌دهد."},{"en":"Concession: \"it is true that the museum is expensive, but...\". The writer’s real view comes after \"but\".","tr":"Kabul etme: \"müzenin pahalı olduğu doğru ama...\". Yazarın asıl görüşü \"but\"tan sonra gelir.","fa":"پذیرش موقت: «درست است که موزه گران است، اما...». نظر واقعی نویسنده بعد از «but» می‌آید."}],"example":{"text":"Critics have called the new gallery cold and unwelcoming. I disagree: its plain white rooms let the paintings speak for themselves, which is exactly what a gallery should do.","item":"Statement: The writer thinks the new gallery is unwelcoming.  (YES / NO / NOT GIVEN)","answer":"NO","why":{"en":"\"Unwelcoming\" is the critics’ view. \"I disagree\" makes the writer’s view the opposite: NO.","tr":"\"Soğuk\" eleştirmenlerin görüşü. \"Katılmıyorum\" yazarın görüşünü tersine çeviriyor: NO.","fa":"«بی‌روح» نظر منتقدهاست. «موافق نیستم» نظر نویسنده را برعکس می‌کند: NO."}},"track":"academic","general":true,"patterns":["RA-history"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Content, opinion, judgement","tr":"İçerik, görüş, yargı","fa":"محتوا، نظر، داوری"},"body":{"en":"Questions 27-32: a summary of the book’s content with a box of ten words, A-J; four are not used. Questions 33-36: YES, NO or NOT GIVEN about the reviewer’s views. Questions 37-40: multiple choice, A-D.","tr":"Soru 27-32: kitabın içeriğinin on kelimelik kutulu (A-J) özeti; dördü kullanılmaz. Soru 33-36: eleştirmenin görüşleri hakkında YES, NO ya da NOT GIVEN. Soru 37-40: çoktan seçmeli, A-D.","fa":"سؤال‌های ۲۷ تا ۳۲: خلاصه‌ی محتوای کتاب با کادر ده‌کلمه‌ای A تا J؛ چهار تا استفاده نمی‌شوند. سؤال‌های ۳۳ تا ۳۶: YES، NO یا NOT GIVEN درباره‌ی نظرهای منتقد. سؤال‌های ۳۷ تا ۴۰: چندگزینه‌ای، A تا D."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Sort facts from judgements","tr":"Gerçekleri yargılardan ayır","fa":"واقعیت را از داوری جدا کن"},"steps":[{"en":"Mark the reviewer’s judgement words as you read: finest, memorable, weakness, hurried, a pity.","tr":"Okurken eleştirmenin yargı kelimelerini işaretle: finest, memorable, weakness, hurried, a pity.","fa":"موقع خواندن کلمه‌های داوری منتقد را علامت بزن: finest، memorable، weakness، hurried، a pity."},{"en":"For the summary, find the facts in order and choose the box word with the same meaning and the right grammar.","tr":"Özet için gerçekleri sırayla bul ve aynı anlamdaki, dilbilgisine uyan kutu kelimesini seç.","fa":"برای خلاصه، واقعیت‌ها را به ترتیب پیدا کن و کلمه‌ای از کادر را انتخاب کن که همان معنی و دستور درست را دارد."},{"en":"For YES / NO / NOT GIVEN, look only at the judgement words: is there a view on this point at all?","tr":"YES / NO / NOT GIVEN için yalnızca yargı kelimelerine bak: bu konuda bir görüş var mı?","fa":"برای YES / NO / NOT GIVEN فقط به کلمه‌های داوری نگاه کن: اصلاً نظری درباره‌ی این نکته هست؟"}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"A topic is not an opinion","tr":"Konu, görüş değildir","fa":"موضوع، نظر نیست"},"body":{"en":"The reviewer may mention a group of readers, a part of the book or a later development without giving any view about it. If there is no judgement, the answer is NOT GIVEN, even when the words match.","tr":"Eleştirmen bir okur grubundan, kitabın bir bölümünden ya da sonraki bir gelişmeden, hakkında hiçbir görüş bildirmeden söz edebilir. Yargı yoksa, kelimeler uysa bile cevap NOT GIVEN’dır.","fa":"منتقد ممکن است از گروهی از خواننده‌ها، بخشی از کتاب یا تحولی بعدی اسم ببرد بدون اینکه نظری درباره‌اش بدهد. اگر داوری‌ای نیست، جواب NOT GIVEN است، حتی اگر کلمه‌ها جور باشند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One YES / NO / NOT GIVEN, step by step","tr":"Bir YES / NO / NOT GIVEN, adım adım","fa":"یک YES / NO / NOT GIVEN، قدم به قدم"},"instruction":"Do the following statements agree with the views of the writer?","text":"\"The author covers the early years of photography in detail. Her account of the first portrait studios is especially vivid.\"","item":"Statement: Students of photography will find the book useful.","answer":"NOT GIVEN","walk":[{"en":"Find the judgement words: \"especially vivid\".","tr":"Yargı kelimelerini bul: \"especially vivid\".","fa":"کلمه‌های داوری را پیدا کن: «especially vivid»."},{"en":"They praise one chapter; they say nothing about students.","tr":"Bir bölümü övüyorlar; öğrenciler hakkında hiçbir şey söylemiyorlar.","fa":"از یک فصل تعریف می‌کنند؛ درباره‌ی دانشجوها چیزی نمی‌گویند."},{"en":"No view on this point: NOT GIVEN.","tr":"Bu konuda görüş yok: NOT GIVEN.","fa":"درباره‌ی این نکته نظری نیست: NOT GIVEN."}]},"quick":{"prompt":"Text: \"The writing is superb; sadly, the index is full of gaps.\" Statement: \"The index is complete and reliable.\" YES, NO or NOT GIVEN?","options":["YES","NO","NOT GIVEN"],"correct":1,"why":{"en":"\"Full of gaps\" is a criticism, so \"complete and reliable\" goes against the reviewer.","tr":"\"Boşluklarla dolu\" bir eleştiri; \"eksiksiz ve güvenilir\" eleştirmenin görüşüyle çelişiyor.","fa":"«پر از کمبود است» انتقاد است، پس «کامل و قابل‌اعتماد» خلاف نظر منتقد است."}},"remember":{"en":"Separate what the book says from what the reviewer thinks, and answer YES or NO only from judgement words.","tr":"Kitabın söylediğini eleştirmenin düşündüğünden ayır; YES ya da NO’yu yalnızca yargı kelimelerinden ver.","fa":"چیزی را که کتاب می‌گوید از نظر منتقد جدا کن و YES یا NO را فقط از روی کلمه‌های داوری بده."},"type":"explain","id":"c-x04-r3-e","course":"ielts-exams","exam":"exam-04","unit":"x04-r3"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 3","title":{"en":"Lines on paper","tr":"Kâğıttaki çizgiler","fa":"خط‌هایی روی کاغذ"},"timed":20,"ctx":["RA-history"],"intro":"You should spend about 20 minutes on Questions 27-40, which are based on Reading Passage 3 below.","passage":"Lines on paper\n\nHelena Strachan spent twenty years repairing old maps for libraries and museums before she wrote a word of this book, and it shows. Lines on Paper: The Mapmaker's Craft is not a history of exploration or of empires, the subjects that most books about maps prefer. It is a history of how maps were physically made: the materials, the tools and, above all, the people who used them. That focus is the book's great strength, and occasionally its weakness. It also means that the heroes of the story are not famous navigators but engravers, printers and surveyors whose names are almost entirely forgotten.\n\nStrachan begins in the centuries before printing, when every map had to be copied by hand. Each copy took weeks, and each one was slightly different from the last, because copyists made mistakes or added details of their own. A map, she reminds us, was not a fixed record but something closer to a rumour, changing a little every time it was passed on. Most of these early maps were made for rulers or merchants, and very few people outside palaces and offices ever saw one.\n\nThe book comes alive when it reaches the sixteenth century and the arrival of engraving. Instead of drawing each map separately, craftsmen cut the lines in reverse into a sheet of copper, covered the plate with ink, wiped the surface clean and pressed damp paper onto it. Hundreds of identical copies could then be printed. Strachan's chapters on this process are, in my view, the finest in the book. She explains how engravers developed a whole vocabulary of marks for hills, forests and towns, and how a single plate might be corrected and reused for a century or more, so that old mistakes survived on maps long after the land itself had changed. Islands that did not exist could appear on maps for generations simply because nobody had cut them out of the plate.\n\nShe is equally good on a group of workers whom most histories ignore. Printed maps came off the press in black and white, and colour was added afterwards by hand, often by teams of colourists working at home, many of them women and children paid by the sheet. Strachan has searched account books and letters to recover some of their names, and her description of a family of colourists working by candlelight to finish an order is one of the most memorable passages in the book.\n\nFrom the eighteenth century, maps also became far more accurate. Governments began to fund careful surveys, measuring the land with chains and instruments and building up networks of triangles across whole countries. Then, in the nineteenth century, lithography, a method of printing from a specially prepared stone, made maps much cheaper to produce, and for the first time ordinary families could afford to own them. Strachan treats this democratic moment with real enthusiasm. She shows how railway companies, schools and newspapers all began to print maps of their own, and how walkers and cyclists bought them in their thousands at the end of the century.\n\nThe book does have weaknesses. The most serious is that its story is almost entirely European. Mapmaking traditions in China, the Islamic world and elsewhere are mentioned in a few paragraphs and then dropped, although their methods and materials were just as interesting. A book that claims to describe \"the mapmaker's craft\" ought to have looked further. The final chapter, which deals with the move from paper to digital maps, also feels hurried. Having spent so long on copper plates, Strachan seems to lose interest once the computer arrives, and the last fifty years are covered in fewer pages than a single engraving workshop.\n\nThere is also a practical problem with the illustrations. The publisher has included many reproductions of old maps, which is welcome, but most are printed so small that the details Strachan describes so carefully are impossible to see. Readers will need a magnifying glass, or a library with the originals. A website with larger images would have solved the problem easily, and it is a pity that nobody thought of it.\n\nThese criticisms should not put anyone off. Strachan writes clearly, without the technical language that makes some books on this subject hard work, and her affection for her subject is obvious on every page. Anyone who has ever unfolded a paper map and wondered how it was made will find this book a pleasure. It is not the complete history of mapmaking that its title promises, but it is an unusually human one.","groups":[{"instruction":"Questions 27-32. Complete the summary using the list of words, A-J, below. Write the correct letter, A-J, in boxes 27-32 on your answer sheet.","qtype":"summary-box","summaryTitle":"How maps were made","bank":["A accurate","B cheaper","C colourists","D copper","E digital","F expensive","G hand","H printers","I stone","J surveys"],"questions":[{"n":27,"kind":"match","prompt":"Before printing, every map had to be copied by ___,","correct":6,"evidence":"every map had to be copied by hand","why":{"en":"\"Every map had to be copied by hand\": hand (G).","tr":"\"Her harita elle kopyalanmak zorundaydı\": hand (G).","fa":"«هر نقشه باید با دست نسخه‌برداری می‌شد»: hand (G)."},"trap":["TR-paraphrase"]},{"n":28,"kind":"match","prompt":"and from the sixteenth century engravers cut the lines into sheets of ___.","correct":3,"evidence":"cut the lines in reverse into a sheet of copper","why":{"en":"\"Cut the lines in reverse into a sheet of copper\": copper (D). Stone (I) belongs to lithography, much later.","tr":"\"Çizgileri ters olarak bir bakır levhaya oydular\": copper (D). Stone (I) çok daha sonraki taş baskıya ait.","fa":"«خط‌ها را برعکس روی ورقه‌ای از مس حک می‌کردند»: copper (D). stone (I) مال لیتوگرافی است، خیلی بعدتر."},"trap":["TR-samewords"]},{"n":29,"kind":"match","prompt":"Colour was then added by hand, often by ___ working at home.","correct":2,"evidence":"often by teams of colourists working at home","why":{"en":"\"Teams of colourists working at home\": colourists (C). Printers (H) produced the black-and-white sheets.","tr":"\"Evde çalışan renklendirici ekipleri\": colourists (C). Printers (H) siyah-beyaz sayfaları basıyordu.","fa":"«گروه‌هایی از رنگ‌کارها که در خانه کار می‌کردند»: colourists (C). printers (H) برگه‌های سیاه‌وسفید را چاپ می‌کردند."},"trap":["TR-samewords","TR-plural"]},{"n":30,"kind":"match","prompt":"In the eighteenth century, careful ___ paid for by governments made maps more accurate.","correct":9,"evidence":"Governments began to fund careful surveys","why":{"en":"\"Governments began to fund careful surveys\": paid for = funded; surveys (J).","tr":"\"Hükümetler titiz ölçümleri finanse etmeye başladı\": paid for = funded; surveys (J).","fa":"«دولت‌ها شروع به تأمین هزینه‌ی نقشه‌برداری‌های دقیق کردند»: paid for یعنی funded؛ surveys (J)."},"trap":["TR-paraphrase","PARA-cause"]},{"n":31,"kind":"match","prompt":"Later, lithography made maps far ___ to produce, so ordinary families could buy them.","correct":1,"evidence":"made maps much cheaper to produce","why":{"en":"\"Made maps much cheaper to produce\": cheaper (B). Expensive (F) is the opposite.","tr":"\"Haritaların üretimini çok daha ucuz hâle getirdi\": cheaper (B). Expensive (F) tersi.","fa":"«تولید نقشه را خیلی ارزان‌تر کرد»: cheaper (B). expensive (F) برعکسش است."},"trap":["TR-paraphrase"]},{"n":32,"kind":"match","prompt":"The last chapter describes the change from paper to ___ maps.","correct":4,"evidence":"the move from paper to digital maps","why":{"en":"\"The move from paper to digital maps\": digital (E).","tr":"\"Kâğıttan dijital haritalara geçiş\": digital (E).","fa":"«گذر از نقشه‌ی کاغذی به دیجیتال»: digital (E)."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 33-36. Do the following statements agree with the views of the writer in Reading Passage 3? In boxes 33-36 on your answer sheet, write YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.","qtype":"ynng","questions":[{"n":33,"kind":"ynng","prompt":"The chapters on engraving are the best part of the book.","correct":"YES","evidence":"Strachan's chapters on this process are, in my view, the finest in the book","why":{"en":"\"In my view, the finest in the book.\"","tr":"\"Bence kitabın en iyi bölümleri.\"","fa":"«به نظر من، بهترین فصل‌های کتاب‌اند»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":34,"kind":"ynng","prompt":"The author gives enough attention to mapmaking outside Europe.","correct":"NO","evidence":"its story is almost entirely European","why":{"en":"\"The most serious\" weakness: the story is \"almost entirely European\"; other traditions are \"mentioned in a few paragraphs and then dropped\".","tr":"\"En ciddi\" zayıflık: hikâye \"neredeyse tamamen Avrupalı\"; diğer gelenekler \"birkaç paragrafta anılıp bırakılıyor\".","fa":"«جدی‌ترین» ضعف: داستان «تقریباً کاملاً اروپایی است»؛ سنت‌های دیگر «در چند پاراگراف ذکر و رها می‌شوند»."},"trap":["TR-whosevoice"]},{"n":35,"kind":"ynng","prompt":"Professional geographers will find the book too simple.","correct":"NOT GIVEN","evidence":"without the technical language that makes some books on this subject hard work","why":{"en":"The reviewer says the book avoids technical language, but gives no view on what professionals will think.","tr":"Eleştirmen kitabın teknik dilden kaçındığını söylüyor ama uzmanların ne düşüneceği hakkında görüş bildirmiyor.","fa":"منتقد می‌گوید کتاب از زبان فنی دوری می‌کند، اما درباره‌ی نظر متخصص‌ها چیزی نمی‌گوید."},"trap":["TR-NGvsF"]},{"n":36,"kind":"ynng","prompt":"The chapter on digital maps is too short.","correct":"YES","evidence":"The final chapter, which deals with the move from paper to digital maps, also feels hurried","why":{"en":"It \"feels hurried\", and fifty years get \"fewer pages than a single engraving workshop\".","tr":"\"Aceleye getirilmiş gibi\" ve elli yıl \"tek bir gravür atölyesinden daha az sayfa\" alıyor.","fa":"«سرسری به نظر می‌رسد» و پنجاه سال «کمتر از یک کارگاه حکاکی صفحه» گرفته."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 37-40. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 37-40 on your answer sheet.","qtype":"mcq","questions":[{"n":37,"kind":"mcq","prompt":"What does the reviewer say about Strachan’s earlier career?","options":["A It explains why the book focuses on how maps were made.","B It made her well known.","C It led to some mistakes.","D It is not mentioned in the book."],"correct":0,"evidence":"before she wrote a word of this book, and it shows","why":{"en":"Twenty years repairing old maps, \"and it shows\": the book is about materials, tools and people.","tr":"Yirmi yıl eski haritaları onarmış \"ve bu belli oluyor\": kitap malzemeler, aletler ve insanlarla ilgili.","fa":"بیست سال نقشه‌های قدیمی را تعمیر کرده «و معلوم است»: کتاب درباره‌ی مواد، ابزار و آدم‌هاست."},"trap":["TR-paraphrase","PARA-cause"]},{"n":38,"kind":"mcq","prompt":"Why does the reviewer describe the colourists?","options":["A to criticise the quality of early maps","B to show that the book brings forgotten workers to light","C to explain why maps were expensive","D to compare the work of men and women"],"correct":1,"evidence":"a group of workers whom most histories ignore","why":{"en":"They are \"workers whom most histories ignore\", and Strachan \"recovers some of their names\".","tr":"\"Çoğu tarih kitabının görmezden geldiği işçiler\" ve Strachan \"bazılarının adlarını gün ışığına çıkarıyor\".","fa":"آن‌ها «کارگرانی‌اند که بیشتر تاریخ‌ها نادیده‌شان می‌گیرند» و استراکن «اسم بعضی‌شان را پیدا کرده»."},"trap":["TR-paraphrase"]},{"n":39,"kind":"mcq","prompt":"What problem does the reviewer mention with the illustrations?","options":["A There are too few of them.","B They are only in black and white.","C They have been badly chosen.","D They are printed too small."],"correct":3,"evidence":"most are printed so small","why":{"en":"The many reproductions are \"welcome\", but \"most are printed so small that the details... are impossible to see\".","tr":"Çok sayıda reprodüksiyon \"iyi\" ama \"çoğu o kadar küçük basılmış ki ayrıntılar görülemiyor\".","fa":"نسخه‌های تصویری زیاد «خوب‌اند»، اما «بیشترشان آن‌قدر کوچک چاپ شده‌اند که جزئیات دیده نمی‌شوند»."},"trap":["TR-samewords"]},{"n":40,"kind":"mcq","prompt":"What is the reviewer’s overall opinion of the book?","options":["A It is the complete history that its title promises.","B It is too technical for most readers.","C It is worth reading, despite its weaknesses.","D It should be rewritten."],"correct":2,"evidence":"These criticisms should not put anyone off","why":{"en":"\"These criticisms should not put anyone off... a pleasure.\" It is \"not the complete history that its title promises\", so A is wrong.","tr":"\"Bu eleştiriler kimseyi vazgeçirmemeli... bir zevk.\" \"Başlığının vaat ettiği eksiksiz tarih değil\", yani A yanlış.","fa":"«این انتقادها نباید کسی را دلسرد کنند... لذت‌بخش است». «آن تاریخ کاملی که عنوانش وعده می‌دهد نیست»، پس A غلط است."},"trap":["TR-whosevoice"]}]}],"id":"c-x04-r3-d","course":"ielts-exams","exam":"exam-04","unit":"x04-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The last chapter feels hurried.\" Hurried means...","options":["done too quickly","very carefully written","too long"],"correct":0,"why":{"en":"Hurried = done in a rush, without enough time or care.","tr":"Hurried = aceleyle, yeterli zaman ya da özen olmadan yapılmış.","fa":"hurried یعنی با عجله، بدون وقت یا دقت کافی."}},{"tests":"paraphrase","point":1,"prompt":"Which phrase means \"should not stop anyone from reading it\"?","options":["should be taken seriously","should be read twice","should not put anyone off"],"correct":2,"why":{"en":"To put someone off = to make them not want to do something.","tr":"Put someone off = birini bir şeyden soğutmak.","fa":"put someone off یعنی کسی را از کاری دلسرد کردن."}},{"tests":"method","point":2,"prompt":"Which words show a reviewer’s judgement rather than a fact about the book?","options":["in the sixteenth century, copper","the finest, memorable, a pity","chapters, pages, illustrations"],"correct":1,"why":{"en":"Judgement words give the reviewer’s opinion; the others are facts or topics.","tr":"Yargı kelimeleri eleştirmenin görüşünü verir; diğerleri gerçekler ya da konular.","fa":"کلمه‌های داوری نظر منتقد را می‌دهند؛ بقیه واقعیت یا موضوع‌اند."}},{"tests":"trap","point":3,"prompt":"Text: \"The book has many photographs, and the author writes about schools in great detail.\" Statement: \"The reviewer thinks teachers will enjoy the book.\" YES, NO or NOT GIVEN?","options":["NOT GIVEN","YES","NO"],"correct":0,"why":{"en":"Schools are a topic, but there is no view about teachers enjoying it.","tr":"Okullar bir konu ama öğretmenlerin kitabı beğeneceğine dair bir görüş yok.","fa":"مدرسه‌ها یک موضوع‌اند، اما درباره‌ی لذت بردن معلم‌ها نظری نیست."}},{"tests":"trap","point":2,"prompt":"A summary box contains both \"faster\" and \"slower\". The gap reads \"the new railway made the journey far ___, so people could reach the coast in a day\". Which word fits?","options":["slower","safer","faster"],"correct":2,"why":{"en":"\"Could reach the coast in a day\" needs the meaning \"taking less time\": faster.","tr":"\"Sahile bir günde varabildiler\" ifadesi \"daha kısa sürede\" anlamını gerektirir: faster.","fa":"«می‌توانستند در یک روز به ساحل برسند» معنی «در زمان کمتر» را می‌خواهد: faster."}}],"id":"c-x04-r3-x","course":"ielts-exams","exam":"exam-04","unit":"x04-r3"},"gt":{"explain":{"title":{"en":"GT Reading Section 3: a long article","tr":"GT Reading Section 3: uzun bir makale","fa":"GT Reading Section 3: یک مقاله‌ی بلند"},"objective":{"en":"In this lesson you will learn to choose a heading for each of seven sections of an article about scientific fieldwork, answer multiple-choice questions on details, and complete a summary with single words.","tr":"Bu derste bilimsel saha çalışması hakkındaki bir makalenin yedi bölümünün her biri için başlık seçmeyi, ayrıntılarla ilgili çoktan seçmeli soruları cevaplamayı ve bir özeti tek kelimelerle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری برای هر کدام از هفت بخش یک مقاله درباره‌ی کار میدانی علمی عنوان انتخاب کنی، به سؤال‌های چندگزینه‌ای درباره‌ی جزئیات جواب بدهی و یک خلاصه را با تک‌کلمه‌ها کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Sections","tr":"Bölüm","fa":"بخش"},"value":"A-G"},{"label":{"en":"Headings","tr":"Başlıklar","fa":"عنوان‌ها"},"value":"i-ix"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: six weeks with the whales","tr":"Bu sınav: balinalarla altı hafta","fa":"این آزمون: شش هفته با نهنگ‌ها"},"intro":{"en":"Section 3 is one long article. Nature and the environment are frequent subjects, often told through a project or an expedition, so each section usually describes one activity or one finding.","tr":"Section 3 tek bir uzun makaledir. Doğa ve çevre sık konulardır, çoğu zaman bir proje ya da keşif gezisi üzerinden anlatılır; bu yüzden her bölüm genelde bir etkinliği ya da bir bulguyu anlatır.","fa":"Section 3 یک مقاله‌ی بلند است. طبیعت و محیط زیست موضوع‌های پرتکرارند و اغلب از طریق یک پروژه یا سفر علمی گفته می‌شوند، پس هر بخش معمولاً یک فعالیت یا یک یافته را توضیح می‌دهد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-r3gt-ctx","exam":true,"patterns":["GT3-nature","PARA-cause"],"often":{"pattern":"GT3-nature","n":12,"of":40,"label":{"en":"Comes up often in the real exam: 12 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 12’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۲ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A research voyage","tr":"Bir araştırma yolculuğu","fa":"یک سفر پژوهشی"},"asks":{"en":"Section 3 is one long article. Here it follows a team studying whales at sea: the aims, three ways of collecting data, life on board, threats to the whales and how the public can help.","tr":"Section 3 tek bir uzun makaledir. Burada denizde balinaları inceleyen bir ekibi izliyor: amaçlar, veri toplamanın üç yolu, gemideki yaşam, balinalara yönelik tehditler ve halkın nasıl yardım edebileceği.","fa":"Section 3 یک مقاله‌ی بلند است. این‌جا گروهی را دنبال می‌کند که در دریا نهنگ‌ها را مطالعه می‌کنند: هدف‌ها، سه راه جمع‌آوری داده، زندگی روی کشتی، خطرهایی که نهنگ‌ها را تهدید می‌کند و اینکه مردم چطور کمک می‌کنند."},"fields":["The aim","Photos","Sound","Samples","Life on board","Threats","Results"],"words":[{"a":"identify","b":"recognise / say which one it is","tr":"tanımlamak, tanımak","fa":"شناسایی کردن"},{"a":"catalogue","b":"a list or collection of records","tr":"katalog","fa":"فهرست، کاتالوگ"},{"a":"underwater microphone","b":"hydrophone","tr":"su altı mikrofonu","fa":"میکروفون زیر آب"},{"a":"estimate","b":"make a rough count","tr":"tahmin etmek","fa":"تخمین زدن"},{"a":"sample","b":"a small amount taken to test","tr":"örnek, numune","fa":"نمونه"},{"a":"routine","b":"the usual order of activities","tr":"günlük düzen","fa":"برنامه‌ی روزمره"},{"a":"collision","b":"a crash","tr":"çarpışma","fa":"برخورد"},{"a":"entanglement","b":"being caught in ropes or nets","tr":"dolanma, takılma","fa":"گیر افتادن"},{"a":"drown out","b":"make too much noise for something to be heard","tr":"bastırmak (ses)","fa":"صدای چیزی را پوشاندن"},{"a":"upload","b":"send to a website","tr":"yüklemek","fa":"بارگذاری کردن"}],"traps":[{"en":"A heading that names one detail (\"the history of whaling\") can look right because one word matches. The heading must cover the whole section.","tr":"Tek bir ayrıntıyı adlandıran bir başlık (\"balina avcılığının tarihi\") bir kelimesi uyduğu için doğru görünebilir. Başlık bütün bölümü kapsamalı.","fa":"عنوانی که یک جزئیات را نام می‌برد («تاریخ شکار نهنگ») ممکن است چون یک کلمه‌اش جور است درست به نظر برسد. عنوان باید کل بخش را پوشش بدهد."},{"en":"MCQ options often repeat words from the right section but change the meaning. Find the sentence the question is about first.","tr":"Çoktan seçmeli seçenekler çoğu zaman doğru bölümden kelimeleri tekrarlar ama anlamı değiştirir. Önce sorunun ilgili olduğu cümleyi bul.","fa":"گزینه‌های چندگزینه‌ای اغلب کلمه‌های بخش درست را تکرار می‌کنند اما معنی را عوض می‌کنند. اول جمله‌ای را که سؤال درباره‌اش است پیدا کن."}],"example":{"text":"\"D  Bats find insects in the dark by making high calls and listening for the echoes. Some can catch a thousand insects in an hour.\"","item":"Best heading for D: i How bats find food at night  ii The number of bats  iii Why bats sleep in the day","answer":"i","why":{"en":"The section explains how bats find insects; the number is one detail.","tr":"Bölüm yarasaların böcekleri nasıl bulduğunu açıklıyor; sayı bir ayrıntı.","fa":"بخش توضیح می‌دهد خفاش‌ها چطور حشره پیدا می‌کنند؛ عدد یک جزئیات است."}}},{"id":"GT3-nature","ctx":["GT3-nature"],"title":{"en":"Nature and the environment","tr":"Doğa ve çevre","fa":"طبیعت و محیط زیست"},"asks":{"en":"A longer text about wildlife or the environment: turtles, storks, farmland returning to nature, plastic in the sea. Multiple choice, summaries and matching features test causes, efforts and results.","tr":"Yaban hayatı ya da çevre hakkında daha uzun bir metin: kaplumbağalar, leylekler, doğaya dönen tarım arazileri, denizdeki plastik. Çoktan seçmeli sorular, özetler ve özellik eşleştirme nedenleri, çabaları ve sonuçları sınar.","fa":"متنی بلندتر درباره‌ی حیات وحش یا محیط زیست: لاک‌پشت‌ها، لک‌لک‌ها، زمین‌های کشاورزی که به طبیعت برمی‌گردند، پلاستیک در دریا. چندگزینه‌ای، خلاصه‌ها و جورکردن ویژگی‌ها علت‌ها، تلاش‌ها و نتیجه‌ها را می‌سنجند."},"fields":["Why did the birds disappear from the area?","What did volunteers do first?","Summary: the young turtles head for the ___.","Which organisation does each statement refer to?"],"words":[{"a":"wildlife","b":"animals and birds","tr":"yaban hayatı","fa":"حیات وحش"},{"a":"habitat","b":"the place where it lives","tr":"yaşam alanı","fa":"زیستگاه"},{"a":"return","b":"come back / reappear","tr":"geri dönmek","fa":"برگشتن"},{"a":"breed","b":"have young / nest","tr":"üremek","fa":"تولیدمثل کردن"},{"a":"pollution","b":"dirty water or air / waste","tr":"kirlilik","fa":"آلودگی"},{"a":"volunteers","b":"unpaid helpers","tr":"gönüllüler","fa":"داوطلب‌ها"},{"a":"monitor","b":"watch and record","tr":"izlemek","fa":"پایش کردن"},{"a":"release","b":"set free","tr":"serbest bırakmak","fa":"رها کردن"},{"a":"population","b":"the number of animals","tr":"popülasyon","fa":"جمعیت"},{"a":"threatened","b":"in danger","tr":"tehdit altında","fa":"در معرض خطر"},{"a":"reintroduce","b":"bring back to an area","tr":"yeniden yerleştirmek","fa":"بازگرداندن به منطقه"},{"a":"rewilding","b":"letting land return to nature","tr":"doğaya geri bırakma","fa":"بازگرداندن زمین به طبیعت"}],"traps":[{"en":"Cause and result in one paragraph: the question may ask for the cause, but the result comes first in the text.","tr":"Neden ve sonuç aynı paragrafta: soru nedeni sorabilir ama metinde önce sonuç gelir.","fa":"علت و نتیجه در یک پاراگراف: سؤال ممکن است علت را بخواهد، ولی در متن اول نتیجه می‌آید."},{"en":"Summary from a box: two words in the box are close in meaning. Check the exact sense.","tr":"Kutudan özet: kutudaki iki kelime anlamca yakındır. Tam anlamı kontrol et.","fa":"خلاصه از جعبه: دو کلمه‌ی جعبه معنی نزدیکی دارند. معنی دقیق را چک کن."}],"example":{"text":"Storks stopped nesting in the region in the 1940s, after the wet meadows where they fed were drained for farming. They returned only when some of the meadows were flooded again in 2016.","item":"Why did storks stop nesting in the region?  A hunting   B the loss of wet meadows   C cold winters","answer":"B","why":{"en":"\"After the wet meadows where they fed were drained\": the cause is the loss of their feeding grounds.","tr":"\"Beslendikleri ıslak çayırlar kurutulduktan sonra\": neden, beslenme alanlarının yok olması.","fa":"«بعد از اینکه چمنزارهای خیسی که در آن غذا می‌خوردند زهکشی شدند»: علت از بین رفتن محل تغذیه است."}},"track":"gt","general":true,"patterns":["GT3-nature"],"often":{"pattern":"GT3-nature","n":12,"of":40,"label":{"en":"Comes up often in the real exam: 12 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 12’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۲ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Seven headings, three questions, a summary","tr":"Yedi başlık, üç soru, bir özet","fa":"هفت عنوان، سه سؤال، یک خلاصه"},"body":{"en":"Questions 28-34: choose a heading, i-ix, for each of seven sections; two headings are extra. Questions 35-37: multiple choice, A-D. Questions 38-40: complete a summary with ONE WORD ONLY.","tr":"Soru 28-34: yedi bölümün her biri için i-ix arasından bir başlık seç; iki başlık fazladır. Soru 35-37: çoktan seçmeli, A-D. Soru 38-40: özeti ONE WORD ONLY ile tamamla.","fa":"سؤال‌های ۲۸ تا ۳۴: برای هر کدام از هفت بخش یک عنوان از i تا ix انتخاب کن؛ دو عنوان اضافه‌اند. سؤال‌های ۳۵ تا ۳۷: چندگزینه‌ای، A تا D. سؤال‌های ۳۸ تا ۴۰: خلاصه را با ONE WORD ONLY کامل کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One activity per section","tr":"Her bölümde bir etkinlik","fa":"هر بخش یک فعالیت"},"steps":[{"en":"Read the first two sentences of each section: they usually name its activity or its point.","tr":"Her bölümün ilk iki cümlesini oku: genelde etkinliğini ya da ana noktasını söylerler.","fa":"دو جمله‌ی اول هر بخش را بخوان: معمولاً فعالیت یا نکته‌ی اصلی‌اش را می‌گویند."},{"en":"Write a short label in the margin (photos, sound, drone), then match the headings.","tr":"Kenara kısa bir etiket yaz (photos, sound, drone), sonra başlıkları eşleştir.","fa":"کنار صفحه یک برچسب کوتاه بنویس (photos، sound، drone) و بعد عنوان‌ها را جور کن."},{"en":"Do the multiple-choice and summary questions after the headings: you will know where to look.","tr":"Çoktan seçmeli ve özet sorularını başlıklardan sonra yap: nereye bakacağını bileceksin.","fa":"سؤال‌های چندگزینه‌ای و خلاصه را بعد از عنوان‌ها انجام بده: می‌دانی کجا را نگاه کنی."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Similar headings","tr":"Benzer başlıklar","fa":"عنوان‌های شبیه"},"body":{"en":"Two headings may both seem to fit one section, for example one about dangers and one about history. Ask what the whole section is about, and remember that each heading is used only once.","tr":"İki başlık da tek bir bölüme uyuyor gibi görünebilir; örneğin biri tehlikeler, biri tarih hakkında. Bütün bölümün ne hakkında olduğunu sor ve her başlığın yalnızca bir kez kullanıldığını unutma.","fa":"ممکن است دو عنوان هر دو به یک بخش بخورند، مثلاً یکی درباره‌ی خطرها و یکی درباره‌ی تاریخ. بپرس کل بخش درباره‌ی چیست و یادت باشد هر عنوان فقط یک بار به کار می‌رود."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One summary gap, step by step","tr":"Bir özet boşluğu, adım adım","fa":"یک جای خالی خلاصه، قدم به قدم"},"instruction":"Complete the summary. Choose ONE WORD ONLY from the text.","text":"\"The seals were counted from the air, using a small plane that flew along the coast at low tide.\"","item":"The seals were counted from a ___ flying along the coast.","answer":"plane","walk":[{"en":"Find the section about counting seals.","tr":"Fokların sayıldığı bölümü bul.","fa":"بخشی را که درباره‌ی شمردن فک‌هاست پیدا کن."},{"en":"\"From a ___ flying\" needs a noun.","tr":"\"From a ___ flying\" bir isim ister.","fa":"«from a ___ flying» یک اسم می‌خواهد."},{"en":"Copy one word: plane (\"small plane\" would be two).","tr":"Tek kelime kopyala: plane (\"small plane\" iki kelime olurdu).","fa":"یک کلمه کپی کن: plane («small plane» دو کلمه می‌شد)."}]},"quick":{"prompt":"A section describes storms, broken equipment and a lost day of work, and ends: \"Even so, the team kept going.\" Which heading fits best?","options":["How the equipment works","The weather in summer","Difficulties at sea"],"correct":2,"why":{"en":"Storms, broken equipment and a lost day are all difficulties; the other headings cover one detail.","tr":"Fırtınalar, bozuk ekipman ve kayıp bir gün hep zorluk; diğer başlıklar tek bir ayrıntıyı kapsıyor.","fa":"طوفان، وسایل خراب و یک روزِ ازدست‌رفته همه دشواری‌اند؛ عنوان‌های دیگر فقط یک جزئیات را پوشش می‌دهند."}},"remember":{"en":"Label each section in your own words, match the heading to the whole section, and use each heading once.","tr":"Her bölümü kendi kelimelerinle etiketle, başlığı bütün bölümle eşleştir ve her başlığı bir kez kullan.","fa":"هر بخش را با کلمه‌های خودت برچسب بزن، عنوان را با کل بخش جور کن و هر عنوان را یک بار به کار ببر."},"type":"explain","id":"c-x04-r3-e-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-r3"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 3","title":{"en":"Six weeks with the whales","tr":"Balinalarla altı hafta","fa":"شش هفته با نهنگ‌ها"},"timed":20,"ctx":["GT3-nature"],"texts":[{"title":"Six weeks with the whales","kind":"article","body":"A  When the research ship Fulmar left harbour in early July, its crew of twelve had one main task: to count the humpback whales that spend the summer feeding in the cold, rich waters off the northern coast, and to find out whether their numbers were rising or falling. The last full count had been made ten years earlier, and since then fishing patterns and sea temperatures had both changed. For six weeks, the scientists and volunteers on board would follow the whales wherever they went, stopping only when storms made work on deck impossible.\n\nB  Counting whales is harder than it sounds, because the same animal may be seen many times. The answer lies in the whale's tail. When a humpback dives, it lifts its tail, or fluke, out of the water, and the black and white pattern on the underside is different for every individual, rather like a human fingerprint. Whenever a whale dived near the ship, a photographer on deck tried to capture a clear image of its fluke. Back in the ship's small laboratory, each photograph was compared with a catalogue of thousands of whales seen in previous years. A good match could tell the team where an animal had been seen before, how old it was and sometimes even which of its calves had survived.\n\nC  Not every whale can be seen, of course. To find the others, the team lowered underwater microphones, called hydrophones, over the side of the ship each evening. Humpbacks are famous for their long, complex songs, which are mostly sung by males on the breeding grounds, but in the feeding areas they also make shorter calls to each other. By listening through the night, the scientists could tell when whales were nearby even in fog or darkness, and could sometimes estimate how many were present. The recordings are also kept for future study, since nobody yet fully understands what the calls mean.\n\nD  One of the most exciting parts of the work involved a small drone. When a whale breathes out, it sends a tall cloud of spray into the air. By flying the drone through this cloud and catching the spray on a dish, the researchers could collect samples that reveal a great deal about the animal's health, including signs of stress, infection and even pregnancy. Only a few years ago, such information could be obtained only by firing a dart into the whale; the drone allows it to be gathered without touching the animal at all. Flying it safely over a moving whale from a rolling ship takes great skill, and the pilot practised for months before the voyage.\n\nE  Life on board followed a strict routine. Watches began at six in the morning, when two people stood on the highest deck with binoculars, recording every sighting. Meals were eaten in shifts so that the watch was never interrupted. Several of the volunteers suffered badly from seasickness in the first week, and space was so limited that four people shared each cabin. Yet almost everyone on board described the voyage as the best experience of their lives. On calm evenings, the whole crew would gather on deck to watch whales feeding in the golden light.\n\nF  The voyage also showed how much pressure the whales are under. Twice the team photographed animals with deep scars from collisions with ships, and one young whale was seen trailing a length of fishing rope from its tail. The hydrophones recorded the constant noise of passing cargo ships, which can drown out the whales' calls and may make it harder for them to find each other. The scientists believe that ship strikes and entanglement in fishing gear are now the greatest dangers the whales face in this area. They hope that their findings will persuade shipping companies to slow down in the busiest feeding grounds during the summer months.\n\nG  By the end of the voyage, the team had identified more than three hundred individual whales, around a third of which had never been recorded before. All of the fluke photographs have now been added to an online catalogue that scientists in other countries can also use, and members of the public are invited to help. Anyone who photographs a humpback, whether from a ferry or a fishing boat, can upload the image, and a computer program will try to match it with a known whale. In this way, a single holiday photograph can add another piece to the story of an animal's life."}],"groups":[{"text":0,"instruction":"Questions 28-34. The text has seven sections, A-G. Choose the correct heading for each section from the list of headings below. Write the correct number, i-ix, in boxes 28-34 on your answer sheet.","qtype":"headings","bank":["i Collecting health data from the air","ii A daily routine at sea","iii Why whales are getting quieter","iv The purpose of the voyage","v Dangers from human activity","vi Recognising each animal by its tail","vii How the public can take part","viii The history of whaling","ix Hearing what cannot be seen"],"questions":[{"n":28,"kind":"match","prompt":"Section A","correct":3,"evidence":"its crew of twelve had one main task","why":{"en":"The crew’s \"one main task\": to count the whales: the purpose of the voyage (iv).","tr":"Mürettebatın \"tek ana görevi\": balinaları saymak; yolculuğun amacı (iv).","fa":"«تنها وظیفه‌ی اصلیِ» خدمه: شمردن نهنگ‌ها؛ هدف سفر (iv)."},"trap":["TR-paraphrase"]},{"n":29,"kind":"match","prompt":"Section B","correct":5,"evidence":"the black and white pattern on the underside is different for every individual","why":{"en":"Each fluke pattern is unique: recognising each animal by its tail (vi).","tr":"Her kuyruk deseni benzersiz: her hayvanı kuyruğundan tanımak (vi).","fa":"طرح هر دم منحصربه‌فرد است: شناختن هر حیوان از روی دمش (vi)."},"trap":["TR-paraphrase"]},{"n":30,"kind":"match","prompt":"Section C","correct":8,"evidence":"the scientists could tell when whales were nearby even in fog or darkness","why":{"en":"Hydrophones find whales that cannot be seen: hearing what cannot be seen (ix). Heading iii repeats \"whales\" but is not in the text.","tr":"Hidrofonlar görülemeyen balinaları buluyor: görülemeyeni duymak (ix). iii başlığı \"whales\"ı tekrar ediyor ama metinde yok.","fa":"هیدروفون‌ها نهنگ‌هایی را پیدا می‌کنند که دیده نمی‌شوند: شنیدن چیزی که دیده نمی‌شود (ix). عنوان iii کلمه‌ی «whales» را تکرار می‌کند اما در متن نیست."},"trap":["TR-samewords"]},{"n":31,"kind":"match","prompt":"Section D","correct":0,"evidence":"By flying the drone through this cloud","why":{"en":"A drone collects breath samples showing health: collecting health data from the air (i).","tr":"Bir dron sağlığı gösteren nefes örnekleri topluyor: sağlık verisini havadan toplamak (i).","fa":"یک پهپاد نمونه‌های نفس را جمع می‌کند که سلامت را نشان می‌دهند: جمع‌آوری داده‌ی سلامت از هوا (i)."},"trap":["TR-paraphrase","TR-detail"]},{"n":32,"kind":"match","prompt":"Section E","correct":1,"evidence":"Life on board followed a strict routine","why":{"en":"Watches, meals in shifts, shared cabins: a daily routine at sea (ii).","tr":"Nöbetler, vardiyalı yemekler, ortak kamaralar: denizde günlük düzen (ii).","fa":"نگهبانی، غذا در نوبت‌ها، کابین مشترک: برنامه‌ی روزمره در دریا (ii)."},"trap":["TR-paraphrase"]},{"n":33,"kind":"match","prompt":"Section F","correct":4,"evidence":"ship strikes and entanglement in fishing gear are now the greatest dangers","why":{"en":"Scars from ships, fishing rope and ship noise: dangers from human activity (v). Whaling history (viii) is never mentioned.","tr":"Gemi yaraları, balık ağı ipi ve gemi gürültüsü: insan faaliyetinden kaynaklanan tehlikeler (v). Balina avcılığının tarihinden (viii) hiç söz edilmiyor.","fa":"زخم‌های برخورد با کشتی، طناب ماهیگیری و صدای کشتی: خطرهای ناشی از فعالیت انسان (v). از تاریخ شکار نهنگ (viii) اصلاً حرفی نیست."},"trap":["TR-samewords","PARA-cause"]},{"n":34,"kind":"match","prompt":"Section G","correct":6,"evidence":"members of the public are invited to help","why":{"en":"Anyone can upload a whale photo: how the public can take part (vii).","tr":"Herkes bir balina fotoğrafı yükleyebilir: halkın nasıl katılabileceği (vii).","fa":"هر کسی می‌تواند عکس نهنگ بارگذاری کند: اینکه مردم چطور مشارکت کنند (vii)."},"trap":["TR-paraphrase"]}]},{"text":0,"instruction":"Questions 35-37. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 35-37 on your answer sheet.","qtype":"mcq","questions":[{"n":35,"kind":"mcq","prompt":"Why did the team need to count the whales again?","options":["A The last count was old and conditions had changed.","B The previous count had been inaccurate.","C Whale numbers had clearly fallen.","D A new ship had become available."],"correct":0,"evidence":"The last full count had been made ten years earlier","why":{"en":"The last count was \"ten years earlier\", and \"fishing patterns and sea temperatures had both changed\".","tr":"Son sayım \"on yıl önce\" yapılmıştı ve \"balıkçılık düzeni de deniz sıcaklıkları da değişmişti\".","fa":"آخرین سرشماری «ده سال پیش» بود و «هم الگوی ماهیگیری و هم دمای دریا عوض شده بود»."},"trap":["TR-detail","PARA-cause"]},{"n":36,"kind":"mcq","prompt":"What is the main advantage of the drone method?","options":["A It is cheaper than other methods.","B Samples can be taken without touching the whale.","C It works best at night.","D Whales are attracted to the drone."],"correct":1,"evidence":"without touching the animal at all","why":{"en":"Information that once needed a dart can now be gathered \"without touching the animal at all\".","tr":"Eskiden ok gerektiren bilgi artık \"hayvana hiç dokunmadan\" toplanabiliyor.","fa":"اطلاعاتی که قبلاً به تیر نیاز داشت حالا «بدون اینکه اصلاً به حیوان دست بزنند» جمع می‌شود."},"trap":["TR-paraphrase"]},{"n":37,"kind":"mcq","prompt":"What did the hydrophones show about ship noise?","options":["A It attracts whales to ships.","B It is louder at night.","C It may stop whales from hearing each other.","D It has fallen in recent years."],"correct":2,"evidence":"which can drown out the whales' calls","why":{"en":"Ship noise \"can drown out the whales’ calls and may make it harder for them to find each other\".","tr":"Gemi gürültüsü \"balinaların seslerini bastırabilir ve birbirlerini bulmalarını zorlaştırabilir\".","fa":"صدای کشتی «می‌تواند صدای نهنگ‌ها را بپوشاند و پیدا کردن همدیگر را برایشان سخت‌تر کند»."},"trap":["TR-paraphrase","PARA-cause"]}]},{"text":0,"instruction":"Questions 38-40. Complete the summary below. Choose ONE WORD ONLY from the text for each answer. Write your answers in boxes 38-40 on your answer sheet.","qtype":"summary","summaryTitle":"Sharing the results","questions":[{"n":38,"kind":"gap","prompt":"All the fluke photographs have now been added to an online ___.","accept":["catalogue"],"limit":1,"evidence":"added to an online catalogue","why":{"en":"\"All of the fluke photographs have now been added to an online catalogue.\"","tr":"\"Tüm kuyruk fotoğrafları artık çevrim içi bir kataloğa eklendi.\"","fa":"«همه‌ی عکس‌های دم حالا به یک کاتالوگ آنلاین اضافه شده‌اند»."},"trap":["TR-limit"]},{"n":39,"kind":"gap","prompt":"Anyone who photographs a humpback can ___ the picture.","accept":["upload"],"limit":1,"evidence":"can upload the image","why":{"en":"\"Can upload the image\": the picture = the image.","tr":"\"Görüntüyü yükleyebilir\": the picture = the image.","fa":"«می‌تواند تصویر را بارگذاری کند»: the picture یعنی the image."},"trap":["TR-paraphrase"]},{"n":40,"kind":"gap","prompt":"A computer ___ then tries to match it with a known whale.","accept":["program"],"limit":1,"evidence":"a computer program will try to match it","why":{"en":"\"A computer program will try to match it with a known whale.\"","tr":"\"Bir bilgisayar programı onu bilinen bir balinayla eşleştirmeye çalışacak.\"","fa":"«یک برنامه‌ی کامپیوتری سعی می‌کند آن را با یک نهنگ شناخته‌شده جور کند»."},"trap":["TR-limit"]}]}],"id":"c-x04-r3-d-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Ship noise can drown out the calls.\" To drown out a sound means to...","options":["make it louder","make it impossible to hear","record it"],"correct":1,"why":{"en":"A louder noise drowns out a quieter one, so it cannot be heard.","tr":"Daha yüksek bir ses daha alçak olanı bastırır, o yüzden duyulamaz.","fa":"صدای بلندتر صدای آرام‌تر را می‌پوشاند، پس شنیده نمی‌شود."}},{"tests":"paraphrase","point":2,"prompt":"A heading says \"Recognising each animal\". Which phrase in a section would match it?","options":["the pattern is different for every individual","the animals travel long distances","the team counted the animals at night"],"correct":0,"why":{"en":"A unique pattern lets you recognise each individual.","tr":"Benzersiz bir desen her bireyi tanımayı sağlar.","fa":"طرح منحصربه‌فرد باعث می‌شود هر فرد را بشناسی."}},{"tests":"method","point":2,"prompt":"An article has seven sections and nine headings. How many headings will you not use?","options":["none","seven","two"],"correct":2,"why":{"en":"Seven sections, nine headings, each heading once: two are left over.","tr":"Yedi bölüm, dokuz başlık, her başlık bir kez: ikisi artar.","fa":"هفت بخش، نُه عنوان، هر عنوان یک بار: دو تا اضافه می‌مانند."}},{"tests":"trap","point":3,"prompt":"A section about dangers to whales mentions one old whaling ship in a single sentence. Which heading fits the section?","options":["a heading about the history of whaling","a heading about modern dangers","either heading"],"correct":1,"why":{"en":"One sentence about whaling is a detail; the section as a whole is about dangers.","tr":"Balina avcılığıyla ilgili tek cümle bir ayrıntı; bölümün tamamı tehlikelerle ilgili.","fa":"یک جمله درباره‌ی شکار نهنگ یک جزئیات است؛ کل بخش درباره‌ی خطرهاست."}}],"id":"c-x04-r3-x-gt","course":"ielts-exams","exam":"exam-04","unit":"x04-r3"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
